const TechBadge = ({ tech }) => {
  const meta = techMeta[tech.name];
  return (
    <div className="flex-shrink-0 flex items-center gap-3 px-6 py-3 rounded-xl bg-slate-800/60 border border-slate-700/50 hover:border-blue-500/30 hover:bg-slate-700/60 transition-all duration-300 group cursor-default">
      {meta ? (
        <span className="flex-shrink-0" style={{ filter: 'drop-shadow(0 0 4px ' + meta.color + '40)' }}>
          {meta.svg}
        </span>
      ) : (
        <span className="text-xl">💻</span>
      )}
      <span className="text-slate-200 font-medium text-sm group-hover:text-white transition-colors whitespace-nowrap">
        {tech.name}
      </span>
    </div>
  );
};

const TechStack = () => {
  const doubled = [...TECHNOLOGIES, ...TECHNOLOGIES];

  return (
    <section className="py-20 px-4 overflow-hidden">
      <div className="max-w-7xl mx-auto">
        <SectionHeader
          tag="Our Tech Stack"
          heading="Built With Modern Technologies"
          subheading="We use the latest tools and frameworks to build scalable, future-proof solutions"
        />
      </div>

      <div className="relative">
        {/* Gradient overlays */}
        <div className="absolute left-0 top-0 bottom-0 w-32 bg-gradient-to-r from-slate-900 to-transparent z-10 pointer-events-none" />
        <div className="absolute right-0 top-0 bottom-0 w-32 bg-gradient-to-l from-slate-900 to-transparent z-10 pointer-events-none" />

        {/* Row 1 */}
        <div className="flex overflow-hidden mb-4">
          <div className="flex gap-4 animate-scroll-left">
            {doubled.map((tech, i) => (
              <TechBadge key={`r1-${i}`} tech={tech} />
            ))}
          </div>
        </div>

        {/* Row 2 - reversed */}
        <div className="flex overflow-hidden">
          <div
            className="flex gap-4 animate-scroll-left"
            style={{ animationDirection: 'reverse', animationDuration: '30s' }}
          >
            {[...doubled].reverse().map((tech, i) => (
              <TechBadge key={`r2-${i}`} tech={tech} />
            ))}
          </div>
        </div>
      </div>

      {/* Stats below */}
      <div className="max-w-7xl mx-auto mt-16">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
          {[
            { label: 'Technologies Mastered', value: '15+' },
            { label: 'Frameworks Used', value: '10+' },
            { label: 'Cloud Platforms', value: '2+' },
            { label: 'Integrations Built', value: '20+' },
          ].map((item, i) => (
            <motion.div
              key={item.label}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.1 }}
              className="text-center p-5 rounded-xl bg-slate-800/30 border border-slate-700/30"
            >
              <p className="text-3xl font-bold gradient-text mb-1">{item.value}</p>
              <p className="text-slate-400 text-sm">{item.label}</p>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default TechStack;
